async function init(){state.data=await fetch('data/genesis.json').then(r=>r.json()).catch(()=>window.GENESIS_DATA);enhanceAppShell();buildChapterPicker();bind();render();renderLibrary();renderTerms();renderHome();renderJourney();updateCount();applyFont();applyLanguage();showView('home');if(!localStorage.getItem('dtb:onboarded'))$('#onboarding').hidden=false}
function enhanceAppShell(){
  const home=$('#homeView');
  const dashboard=document.createElement('section');dashboard.className='home-dashboard';dashboard.innerHTML=`<div class="welcome-row"><div><small>DECODING THE BIBLE · CODY</small><h2>Volvé a la palabra.</h2></div><button class="profile-orb" aria-label="Abrir ajustes">C</button></div><button class="cody-companion" data-view="cody"><span class="cody-avatar">✦</span><span><b>CODY está acá</b><small>¿Qué querés abrir hoy?</small></span><strong>→</strong></button><div class="app-quick-actions"><button data-view="library"><span>▥</span><b>Biblioteca</b><small>Génesis 1–50</small></button><button data-view="experiences"><span>✧</span><b>Experiencias</b><small>4 portales</small></button><button data-view="journey"><span>◎</span><b>Recorridos</b><small>7 umbrales</small></button></div><div class="daily-progress"><div><small>PROGRESO DE GÉNESIS</small><b><span id="homeChapterCount">0</span> capítulos explorados</b></div><div class="mini-progress"><i id="homeProgressFill"></i></div><button data-view="reader">Continuar →</button></div>`;home.insertBefore(dashboard,home.querySelector('.book-one-hero'));
  const nav=$('.drawer nav');if(nav&&!nav.querySelector('[data-view="settings"]')){const b=document.createElement('button');b.className='nav';b.dataset.view='settings';b.textContent='⚙ Ajustes';nav.appendChild(b)}
  const main=$('main');if(main&&!$('#settingsView')){const sec=document.createElement('section');sec.id='settingsView';sec.className='view settings-view';sec.innerHTML=`<div class="screen-head"><p>PERSONALIZÁ TU LECTURA</p><h1>Ajustes</h1><span>La app se adapta a tu forma de leer.</span></div><div class="settings-group"><label>IDIOMA</label><div class="settings-segment"><button data-set-lang="es">Español</button><button data-set-lang="en">English</button></div></div><div class="settings-group"><label>TAMAÑO DE TEXTO</label><div class="settings-segment"><button id="settingsFontDown">A−</button><button id="settingsFontReset">A</button><button id="settingsFontUp">A+</button></div></div><div class="settings-group"><label>DATOS GUARDADOS EN ESTE DISPOSITIVO</label><button class="settings-row" id="settingsDownload">↓ <span>Descargar mi cuaderno</span> <b>→</b></button><button class="settings-row danger" id="settingsClear">♲ <span>Borrar datos locales</span> <b>→</b></button></div><div class="settings-about"><b>Decoding the Bible · CODY</b><small>Hebreo OSHB/WLC · Génesis 1–50</small></div>`;main.appendChild(sec)}
}
function buildChapterPicker(){const old=$('.chapter-switch');if(old){const select=document.createElement('select');select.id='chapterPicker';select.setAttribute('aria-label','Elegir capítulo de Génesis');select.innerHTML=Object.keys(state.data.chapters).map(c=>`<option value="${c}">Cap. ${c}</option>`).join('');old.replaceWith(select);select.value=state.chapter;select.onchange=()=>{state.chapter=+select.value;localStorage.setItem('dtb:chapter',state.chapter);render()}}const status=$('.library-status');if(status)status.innerHTML='<strong>Génesis · 50 capítulos en hebreo</strong><span>CODY está publicado en Génesis 1–2 y se amplía por etapas editoriales. Los testigos del desierto aparecen solo donde existe evidencia conservada.</span>';const search=$('#searchInput');if(search)search.placeholder='Buscar en Génesis 1–50…'}
function bind(){
  $$('[data-chapter]').forEach(b=>{b.classList.toggle('active',+b.dataset.chapter===state.chapter);b.onclick=()=>{state.chapter=+b.dataset.chapter;localStorage.setItem('dtb:chapter',state.chapter);$$('[data-chapter]').forEach(x=>x.classList.toggle('active',x===b));render()}});
  $$('[data-layer]').forEach(b=>b.onclick=()=>{state.layer=b.dataset.layer;$$('[data-layer]').forEach(x=>x.classList.toggle('active',x===b));render()});
  $$('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));
  $('#closeDialog').onclick=()=>$('#decodeDialog').close();$('#closeVerseDialog').onclick=()=>$('#verseDialog').close(); $('#searchBtn').onclick=()=>{$('#searchDialog').showModal();$('#searchInput').focus()};
  $('#langBtn').onclick=()=>setLanguage(state.lang==='es'?'en':'es');$$('[data-set-lang]').forEach(b=>b.onclick=()=>setLanguage(b.dataset.setLang));$('#startApp').onclick=()=>{localStorage.setItem('dtb:onboarded','1');$('#onboarding').hidden=true;showView('home')};
  $('#searchInput').oninput=e=>search(e.target.value);
  $('#continueReading').onclick=()=>showView('reader');
  $('#enterBookOne').onclick=()=>showView('reader');
  $('#backLibrary').onclick=()=>showView('library');$('#bookPicker').onclick=()=>showView('library');
  $('#fontDown').onclick=()=>setFont(-.1);$('#fontUp').onclick=()=>setFont(.1);$('#focusMode').onclick=()=>document.body.classList.toggle('focus');
  $('#savePersonalNote').onclick=savePersonalNote;$('#downloadNotebook').onclick=downloadNotebook;
  const toggleMenu=on=>{$('#drawer').classList.toggle('open',on);$('#scrim').classList.toggle('show',on)};
  $('#menuBtn').onclick=()=>toggleMenu(true);$('#scrim').onclick=()=>toggleMenu(false);
  $$('[data-view]').forEach(b=>b.addEventListener('click',()=>toggleMenu(false)));
  const toggleSheet=()=>$('#readerSheet').classList.toggle('open');$('#readerFab').onclick=toggleSheet;$('#fontBtn').onclick=toggleSheet;
  $('#todayDate').textContent=new Intl.DateTimeFormat('es-AR',{weekday:'long',day:'numeric',month:'long'}).format(new Date()).toUpperCase();
  window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#installBtn').hidden=false});
  $('#installBtn').onclick=async()=>{if(installPrompt){installPrompt.prompt();await installPrompt.userChoice;installPrompt=null}else alert('En iPhone: Compartir → Agregar a inicio. En computadora: usá Instalar en el menú del navegador.')};
  $('#settingsFontDown')?.addEventListener('click',()=>setFont(-.1));$('#settingsFontUp')?.addEventListener('click',()=>setFont(.1));$('#settingsFontReset')?.addEventListener('click',()=>{state.font=1;applyFont()});$('#settingsDownload')?.addEventListener('click',downloadNotebook);$('#settingsClear')?.addEventListener('click',()=>{if(confirm('¿Borrar tus notas, marcas y progreso de este dispositivo?')){localStorage.removeItem('dtb:saved');localStorage.removeItem('dtb:read');localStorage.removeItem('dtb:opened');localStorage.removeItem('dtb:steps');location.reload()}});$('.profile-orb')?.addEventListener('click',()=>showView('settings'));
  $$('[data-game]').forEach(b=>b.onclick=()=>openGame(b.dataset.game));
}
function showView(v){$$('.view').forEach(x=>x.classList.remove('active'));$('#'+v+'View').classList.add('active');document.body.dataset.view=v;$$('[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===v));const t=ui[state.lang];$('#topContext').textContent={home:t.today,library:t.library,reader:t.genesis,experiences:t.experiences,journey:state.lang==='es'?'Recorridos':'Journeys',cody:'CODY',saved:t.notebook,about:state.lang==='es'?'Créditos':'Credits'}[v]||'';if(v==='saved')renderSaved();if(v==='home')renderHome();scrollTo({top:0,behavior:'smooth'})}
function setLanguage(lang){state.lang=lang;localStorage.setItem('dtb:lang',lang);applyLanguage();renderLibrary()}
function applyLanguage(){document.documentElement.lang=state.lang;$('#langBtn').textContent=state.lang.toUpperCase();$$('[data-i18n]').forEach(el=>el.textContent=ui[state.lang][el.dataset.i18n]);const current=$('.view.active')?.id?.replace('View','')||'home';$('#topContext').textContent={home:ui[state.lang].today,library:ui[state.lang].library,reader:ui[state.lang].genesis,experiences:ui[state.lang].experiences,journey:state.lang==='es'?'Recorridos':'Journeys',cody:'CODY',saved:ui[state.lang].notebook,about:state.lang==='es'?'Créditos':'Credits'}[current]}
function renderLibrary(){const t=ui[state.lang];$('#libraryShelves').innerHTML=Object.entries(tanakh).map(([section,books])=>`<section class="canon-shelf"><div class="shelf-title"><h2>${section}</h2><span>${books.length} ${state.lang==='es'?'VOLÚMENES':'VOLUMES'}</span></div><div class="book-row">${books.map(([name,hebrew,chapters,open],i)=>`<button class="library-book ${open?'available':'locked'}" ${open?'data-open-genesis="true"':''}><span class="book-number">${String(i+1).padStart(2,'0')}</span><b>${hebrew}</b><strong>${open?t.genesis:name}</strong><small>${chapters} ${t.chapters}</small><i>${open?t.open:t.soon}</i></button>`).join('')}</div></section>`).join('');$$('[data-open-genesis]').forEach(b=>b.onclick=()=>showView('reader'))}
function render(){const ch=state.data.chapters[state.chapter]||[];const codyAvailable=ch.some(v=>v.text);$('#chapterTitle').innerHTML=`Génesis <em>${state.chapter}</em>`;$('#chapterArtwork').src=state.chapter===1?'assets/genesis-threshold.jpg':'assets/adam-adamah.jpg';$('#chapterArtwork').alt=state.chapter===1?'Las aguas primordiales atravesadas por luz y signos hebreos':'El adam emergiendo de la adamah';const picker=$('#chapterPicker');if(picker)picker.value=state.chapter;const status=$('#layerStatus');if(status)status.textContent=state.layer==='cody'?(codyAvailable?'Traducción CODY revisada para este capítulo.':'CODY está en preparación para este capítulo · podés leer el hebreo ahora.'):'Texto hebreo · OSHB / Códice de Leningrado';$('#verses').innerHTML=ch.map(v=>{let txt=state.layer==='hebrew'?(v.hebrew||'Texto hebreo no disponible'):v.text?notesIn(v.text):`<span class="cody-pending">CODY en preparación para este versículo.<br><small>Disponible ahora en עברית.</small></span>`;let key=`${state.chapter}:${v.number}`;return `<section class="verse ${state.layer==='hebrew'?'hebrew':''}" id="v-${key.replace(':','-')}"><span class="verse-num">${v.number}</span><p class="verse-text">${txt}<button class="bookmark ${state.saved.some(x=>x.type==='verse'&&x.key===key)?'saved':''}" data-save-verse="${key}" aria-label="Guardar">◇</button></p></section>`}).join('');
  $$('[data-note]').forEach(b=>b.onclick=()=>openNote(+b.dataset.note));$$('[data-save-verse]').forEach(b=>b.onclick=()=>toggleVerse(b.dataset.saveVerse,b));$$('.verse').forEach(v=>v.onclick=e=>{if(!e.target.closest('button'))openVerseActions(v.id.replace('v-','').replace('-',':'))});
  verseObserver?.disconnect();verseObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting&&!state.read.includes(e.target.id)){state.read.push(e.target.id);localStorage.setItem('dtb:read',JSON.stringify(state.read));renderHome()}}),{threshold:.65});$$('.verse').forEach(v=>verseObserver.observe(v));
}
function notesIn(t){return (t||'').replace(/[⁰¹²³⁴⁵⁶⁷⁸⁹]+/g,m=>{const n=+[...m].map(c=>SUP[c]).join('');return `<button class="note-ref" data-note="${n}" aria-label="Abrir nota ${n}">${n}</button>`})}
function openNote(n){const note=state.data.notes.find(x=>x.id===n);if(!note)return;if(!state.opened.includes(n)){state.opened.push(n);localStorage.setItem('dtb:opened',JSON.stringify(state.opened))}const saved=state.saved.some(x=>x.type==='note'&&x.key==n);$('#decodeContent').innerHTML=`<p class="decode-kicker">VERBUM REVELANS · ${String(n).padStart(2,'0')}</p><div class="decode-hebrew">${note.hebrew||''}</div><h2 class="decode-title">${note.title}</h2><div>${(note.evidence||[]).map(e=>`<span class="evidence ${e[0]==='D'?'d':''}">${e}</span>`).join('')}</div><h3 class="layer-label">CAMPO LINGÜÍSTICO + DECISIÓN CODY</h3><p class="decode-body">${note.body}</p><p class="source-line">Fuente base: OSHB / WLC. Las etiquetas separan evidencia e interpretación.</p><div class="decode-actions"><button class="primary" id="saveNote">${saved?'Guardado':'Guardar lectura'}</button><button class="secondary" id="backVerse">Volver al versículo</button></div>`;$('#decodeDialog').showModal();$('#saveNote').onclick=()=>toggleNote(note);$('#backVerse').onclick=()=>$('#decodeDialog').close();renderHome()}
function toggleNote(note){const i=state.saved.findIndex(x=>x.type==='note'&&x.key==note.id);if(i>=0)state.saved.splice(i,1);else state.saved.push({type:'note',key:note.id,title:note.title,text:note.body});save();$('#decodeDialog').close()}
function toggleVerse(key,b){const i=state.saved.findIndex(x=>x.type==='verse'&&x.key===key);if(i>=0)state.saved.splice(i,1);else{const [c,n]=key.split(':');const v=state.data.chapters[c].find(x=>x.number===n);state.saved.push({type:'verse',key,title:`Génesis ${key}`,text:v.text.replace(/[⁰¹²³⁴⁵⁶⁷⁸⁹]+/g,'')})}save();b.classList.toggle('saved')}
function openVerseActions(key){const [c,n]=key.split(':'),v=state.data.chapters[c].find(x=>x.number===n),clean=v.text.replace(/[⁰¹²³⁴⁵⁶⁷⁸⁹]+/g,'');$('#verseActionContent').innerHTML=`<p class="decode-kicker">GÉNESIS ${key}</p><h2 class="verse-sheet-title">${clean}</h2><div class="verse-action-grid"><button id="sheetSave">◇<span>Guardar</span></button><button id="sheetDecode">◉<span>Abrir CODY</span></button><button id="sheetNote">＋<span>Anotar</span></button><button id="sheetShare">↗<span>Compartir</span></button></div><p class="source-line">Tocá fuera del panel para volver a la lectura.</p>`;$('#verseDialog').showModal();$('#sheetSave').onclick=()=>{toggleVerse(key,$(`[data-save-verse="${key}"]`));$('#verseDialog').close()};$('#sheetDecode').onclick=()=>{const match=[...v.text.matchAll(/[⁰¹²³⁴⁵⁶⁷⁸⁹]+/g)][0];$('#verseDialog').close();match?openNote(+[...match[0]].map(x=>SUP[x]).join('')):showView('cody')};$('#sheetNote').onclick=()=>{$('#verseDialog').close();showView('saved');$('#personalNote').value=`Génesis ${key} — `;$('#personalNote').focus()};$('#sheetShare').onclick=async()=>{const text=`Génesis ${key} — ${clean}`;if(navigator.share)await navigator.share({title:`Génesis ${key}`,text});else{await navigator.clipboard.writeText(text);$('#sheetShare span').textContent='Copiado'}}}
function renderTerms(){const featured=[1,3,5,6,9,14,16,22,28,30,32,35];$('#termGrid').innerHTML=featured.map(n=>{const x=state.data.notes.find(a=>a.id===n);return `<button class="term-card" data-card-note="${n}"><div class="hebrew">${x.hebrew||'—'}</div><h3>${x.title}</h3><p>${x.teaser||'Abrir campo lingüístico y decisión CODY.'}</p></button>`}).join('');$$('[data-card-note]').forEach(b=>b.onclick=()=>openNote(+b.dataset.cardNote))}
function renderSaved(){const el=$('#savedList');el.innerHTML=state.saved.length?state.saved.slice().reverse().map((x,i)=>`<article class="saved-item"><strong>${x.type==='verse'?x.title:x.type==='personal'?'NOTA PERSONAL':'VERBUM REVELANS'}</strong><p>${x.type==='note'?x.title:x.text}</p><button class="remove-save" data-remove="${state.saved.length-1-i}" aria-label="Eliminar">×</button></article>`).join(''):'<article class="saved-item"><p>Todavía no guardaste ninguna marca. Tocá ◇ junto a un versículo o guardá una decodificación CODY.</p></article>';$$('[data-remove]').forEach(b=>b.onclick=()=>{state.saved.splice(+b.dataset.remove,1);save();renderSaved();renderHome()})}
function renderHome(){if(!state.data)return;const day=(new Date().getDate()-1)%state.data.notes.length+1,n=state.data.notes.find(x=>x.id===day);$('#dailyCard').innerHTML=`<div class="daily-hebrew">${n.hebrew}</div><div><h2>${n.title}</h2><p>${n.teaser||'Una palabra, su campo y la decisión que abre.'}</p></div>`;$('#dailyCard').onclick=()=>openNote(n.id);const done=state.steps.length,p=Math.round(done/journey.length*100);$('#progressPercent').textContent=p+'%';$('.ring').style.setProperty('--p',p+'%');$('#readingFill').style.width=Math.max(8,Math.min(100,state.read.length/53*100))+'%';$('#continueChapter').textContent=state.chapter;$('#stepPreview').innerHTML=`<strong>${done===7?'Recorrido completo':journey[done][0]}</strong><small>${done===7?'Volvé a atravesarlo desde otra palabra.':journey[done][2]}</small>`;$('#readStat').textContent=Math.min(state.read.length,53);$('#decodedStat').textContent=state.opened.length;$('#savedStat').textContent=state.saved.length}
function renderJourney(){const art={0:'assets/genesis-threshold.jpg',4:'assets/adam-adamah.jpg',6:'assets/ezer-kenegdo.jpg'};$('#journeySteps').innerHTML=journey.map((s,i)=>`<article class="journey-step ${state.steps.includes(i)?'done':''}">${art[i]?`<img class="journey-art" src="${art[i]}" alt="Ilustración de ${s[0]}">`:''}<span>${String(i+1).padStart(2,'0')}</span><div><small>${s[1]}</small><h2>${s[0]}</h2><p>${s[2]}</p><div class="step-terms">${s[3].map(n=>{const x=state.data.notes.find(a=>a.id===n);return `<button data-card-note="${n}">${x?.hebrew||n}</button>`}).join('')}</div></div><button class="complete-step" data-step="${i}">${state.steps.includes(i)?'Atravesado ✓':'Marcar atravesado'}</button></article>`).join('');$$('[data-card-note]').forEach(b=>b.onclick=()=>openNote(+b.dataset.cardNote));$$('[data-step]').forEach(b=>b.onclick=()=>{const i=+b.dataset.step,p=state.steps.indexOf(i);p>=0?state.steps.splice(p,1):state.steps.push(i);localStorage.setItem('dtb:steps',JSON.stringify(state.steps));renderJourney();renderHome()})}
function savePersonalNote(){const t=$('#personalNote').value.trim();if(!t)return;state.saved.push({type:'personal',key:Date.now(),text:t});$('#personalNote').value='';save();renderSaved();renderHome()}
function downloadNotebook(){const lines=state.saved.map(x=>`## ${x.title||'Nota personal'}\n${x.text||x.title}`).join('\n\n');const blob=new Blob([`# Decoding the Bible · Mi cuaderno CODY\n\n${lines}`],{type:'text/markdown'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='mi-cuaderno-cody.md';a.click();URL.revokeObjectURL(a.href)}
function setFont(d){state.font=Math.max(.8,Math.min(1.4,state.font+d));localStorage.setItem('dtb:font',state.font);applyFont()}
function applyFont(){document.documentElement.style.setProperty('--reader-scale',state.font)}
function openGame(type){const s=$('#gameStage');$$('[data-game]').forEach(b=>b.classList.toggle('active',b.dataset.game===type));if(type==='scratch'){s.innerHTML=`<div class="game-head"><small>LEVANTAR EL VELO</small><h2>¿Qué escondió “bueno”?</h2><p>Raspá con el dedo.</p></div><div class="scratch-wrap"><div class="scratch-reveal"><b>טוֹב · TOV</b><strong>EN CONDICIÓN</strong><p>No describe primero una virtud moral. Señala que algo funciona como corresponde dentro del mundo que el texto organiza.</p></div><canvas id="scratchCanvas"></canvas></div><button class="game-next" id="scratchNext">Otra raspadita</button>`;setupScratch();$('#scratchNext').onclick=()=>openGame('scratch')}
  if(type==='wheel'){const terms=state.data.notes.filter(x=>x.hebrew).slice(0,18);s.innerHTML=`<div class="game-head"><small>PALABRA ERRANTE</small><h2>Una entrada inesperada</h2><p>Girarla no predice nada: cambia tu punto de entrada.</p></div><div class="word-wheel" id="wordWheel"><span>א</span></div><button class="game-next" id="spinWord">Girar</button><div id="wheelResult"></div>`;$('#spinWord').onclick=()=>{const n=terms[Math.floor(Math.random()*terms.length)];$('#wordWheel').classList.remove('spin');void $('#wordWheel').offsetWidth;$('#wordWheel').classList.add('spin');setTimeout(()=>{$('#wheelResult').innerHTML=`<button data-wheel-note="${n.id}"><b>${n.hebrew}</b><span>${n.title}</span><small>Abrir con CODY →</small></button>`;$('[data-wheel-note]').onclick=()=>openNote(n.id)},850)}}
  if(type==='quiz'){const q=[['“Tov” significa moralmente bueno.',false,'En Génesis 1, CODY lo trabaja primero como aptitud o funcionamiento.'],['“Nephesh chayah” se usa primero para animales.',true,'Sí. Luego la misma expresión se aplica al adam.'],['Toda lectura CODY es evidencia E1.',false,'No. CODY separa evidencia E1–E3 de interpretación D1–D2.']];let i=0,score=0;const draw=()=>{const x=q[i];s.innerHTML=`<div class="game-head"><small>¿DATO O LECTURA? · ${i+1}/3</small><h2>${x[0]}</h2></div><div class="quiz-actions"><button data-answer="true">VERDADERO</button><button data-answer="false">FALSO</button></div><p id="quizFeedback"></p>`;$$('[data-answer]').forEach(b=>b.onclick=()=>{const ok=(b.dataset.answer==='true')===x[1];if(ok)score++;$('#quizFeedback').innerHTML=`<strong>${ok?'Bien visto':'Revisemos'}</strong>${x[2]}`;$$('[data-answer]').forEach(z=>z.disabled=true);setTimeout(()=>{i++;i<q.length?draw():s.innerHTML=`<div class="game-head"><small>RECORRIDO COMPLETO</small><h2>${score}/3 distinciones</h2><p>No se trata de acertar: se trata de aprender dónde termina el dato.</p></div><button class="game-next" id="quizAgain">Volver a intentar</button>`;$('#quizAgain')&&($('#quizAgain').onclick=draw)},1200)})};draw()}
  if(type==='cards'){const cards=state.data.notes.filter(x=>x.hebrew).slice(0,12);let i=0;const draw=()=>{const x=cards[i];s.innerHTML=`<div class="game-head"><small>MEMORIA DE RAÍZ · ${i+1}/${cards.length}</small><h2>No memorices la respuesta. Recordá la tensión.</h2></div><button class="memory-card" id="memoryCard"><span class="front"><b>${x.hebrew}</b><small>Tocá para dar vuelta</small></span><span class="back"><b>${x.title}</b><p>${x.teaser||x.body.slice(0,150)+'…'}</p></span></button><button class="game-next" id="nextCard">Siguiente palabra →</button>`;$('#memoryCard').onclick=()=>$('#memoryCard').classList.toggle('flipped');$('#nextCard').onclick=()=>{i=(i+1)%cards.length;draw()}};draw()}}
function setupScratch(){const c=$('#scratchCanvas'),box=c.parentElement,r=box.getBoundingClientRect(),d=devicePixelRatio||1;c.width=r.width*d;c.height=r.height*d;c.style.width=r.width+'px';c.style.height=r.height+'px';const x=c.getContext('2d');x.scale(d,d);const g=x.createLinearGradient(0,0,r.width,r.height);g.addColorStop(0,'#8b6a32');g.addColorStop(.5,'#e0bd68');g.addColorStop(1,'#765323');x.fillStyle=g;x.fillRect(0,0,r.width,r.height);x.fillStyle='#24170f';x.font='600 14px system-ui';x.textAlign='center';x.fillText('RASPÁ PARA REVELAR',r.width/2,r.height/2);let down=false,last=null;const draw=e=>{if(!down)return;const p=e.touches?.[0]||e,q=c.getBoundingClientRect(),nx=p.clientX-q.left,ny=p.clientY-q.top;x.globalCompositeOperation='destination-out';x.lineWidth=38;x.lineCap='round';x.beginPath();if(last)x.moveTo(last[0],last[1]);x.lineTo(nx,ny);x.stroke();last=[nx,ny]};c.onpointerdown=e=>{down=true;last=null;c.setPointerCapture(e.pointerId);draw(e)};c.onpointermove=draw;c.onpointerup=()=>{down=false;last=null}}
function search(q){q=q.trim().toLowerCase();if(!q){$('#searchResults').innerHTML='';return}let out=[];for(const [c,vs] of Object.entries(state.data.chapters))for(const v of vs)if(v.text.toLowerCase().includes(q))out.push({c,v});$('#searchResults').innerHTML=out.slice(0,20).map(x=>`<button class="search-result" data-hit="${x.c}:${x.v.number}"><strong>Génesis ${x.c}:${x.v.number}</strong><br>${x.v.text}</button>`).join('')||'<p>Sin resultados.</p>';$$('[data-hit]').forEach(b=>b.onclick=()=>{const [c,n]=b.dataset.hit.split(':');state.chapter=+c;$$('[data-chapter]').forEach(x=>x.classList.toggle('active',+x.dataset.chapter===state.chapter));render();$('#searchDialog').close();showView('reader');setTimeout(()=>$('#v-'+c+'-'+n)?.scrollIntoView({behavior:'smooth',block:'center'}),80)})}
function relabelCodi(){const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let n;while(n=walker.nextNode())if(n.nodeValue.includes('CODY'))n.nodeValue=n.nodeValue.replaceAll('CODY','CODI');document.title=document.title.replaceAll('CODY','CODI')}
new MutationObserver(relabelCodi).observe(document.body,{subtree:true,childList:true,characterData:true});
if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js',{updateViaCache:'none'});
init().catch(e=>{console.error(e);$('#verses').innerHTML='<p>No se pudo cargar el texto.</p>'});
